"""Build ten deep, lazy-loaded ECO trees with original Russian study guides."""
import json
from pathlib import Path
import chess
ROOT=Path(__file__).resolve().parents[1]
GUIDES={
'italian':('Italian Game','Итальянская партия','Завершите Nf3, Bc4 и рокировку. В тихой игре готовьте c3 и d4; после d3 сначала укрепите e4. Слона c4 сохраняйте, если размен не решает конкретную задачу.','Развивайте Nc6, Bc5 или Nf6, рокируйте. При Ng5 проверьте контрудар d5, а не только прямую защиту f7. После c3 и d4 белых решайте, выгодно ли вскрывать центр.','f7 — ориентир атаки; e4 и e5 — пешки, требующие защиты. Открытая линия e после разменов повышает значение темпов.','Ранний выход ферзя без угроз; охота за f7 без расчёта; лишние ходы слоном вместо рокировки.','Закрытый центр: подготовьте пешечный подрыв. Открытый центр: активизируйте ладьи, не гоняйтесь за фланговыми пешками.'),
'ruy':('Ruy Lopez','Испанская партия','Слон b5 давит на защитника e5. После a6 верните его на a4, затем b3. Готовьте c3 и d4; ладья e1 поддерживает e4. Сравнивайте закрытый центр с моментом его вскрытия.','Укрепите e5, завершите развитие и рокировку. Рассмотрите своевременный d5; ферзевый фланг a6 и b5 требует защиты и не должен заменять борьбу за центр.','Конь c6 защищает e5. После размена Bxc6 удвоенные пешки чёрных не означают автоматического проигрыша; важны пара слонов и контригра.','Преждевременный Nxe5 без проверки Qd4; атака пешками перед королём; заучивание манёвров без контроля центра.','Переведите коня к устойчивому центральному полю. Перед d4 подготовьте фигуры к размену пешек.'),
'scotch':('Scotch Game','Шотландская партия','d4 сразу оспаривает центр. После exd4 конь обычно возвращает пешку. Развивайте слонов, рокируйте и считайте удары по коню d4 и пешке e4.','Выбирайте давление Bc5 или Nf6. Нападайте на центр с развитием, не старайтесь любой ценой удержать взятую пешку.','После размена центральных пешек открываются линии. В структуре Nxc6 bxc6 чёрные получают пешечный центр, но пешки могут стать мишенями.','Слишком ранний ферзь; непроверенный e5; отсутствие рокировки при вскрытой линии e.','Сначала развитие и король, затем атака центральных слабостей и открытых линий.'),
'sicilian':('Sicilian Defense','Сицилианская защита','После Nf3 и d4 белые получают быстрое развитие; выбирайте расстановку под структуру чёрных. В закрытых системах не начинайте атаку f-пешкой до проверки контрудара в центре.','c5 борется за d4. В открытой сицилианской используйте полуоткрытую линию c, следите за d5 и безопасностью короля. d6/e6/g6 ведут к разным структурам и планам.','Размен c-пешки на d-пешку создаёт асимметрию. Поле d5, пешка d6 и диагональ g7–a1 особенно важны в соответствующих структурах.','Копирование плана Найдорфа в Драконе; фланговая атака без развития; игнорирование жертв на e6 или d5.','Определите структуру: e6 или d6, фианкетто или слон e7. Потом выбирайте центральный подрыв и нужную открытую линию.'),
'french':('French Defense','Французская защита','При e5 используйте пространство, но следите за основанием цепи d4. Подготовьте поддержку центра и развитие слона c1; учитывайте давление Qb6 и c5.','Атакуйте основание цепи ходом c5, вершину — иногда f6. Развивайте фигуры за пешечной цепью, найдите план для слона c8. Не вскрывайте короля без расчёта.','В цепи d4–e5 основание d4 поддерживает e5. После разменов на d4 слабые поля и открытая линия c меняют планы.','Защита каждой пешки без развития; необоснованный f6; размен хорошего слона без компенсации.','Назовите цель подрыва: d4 или e5. Подведите фигуры перед вскрытием и проверьте тактические последствия.'),
'caro':('Caro-Kann Defense','Защита Каро-Канн','Выберите продвижение e5, размен или Nc3. Не считайте спокойную позицию безопасной автоматически: проверяйте давление на центр и вовремя рокируйте.','Пешка c6 поддерживает d5. Выведите слона c8 до e6, когда это допускает вариант. При e5 белых готовьте c5; после разменов используйте устойчивую структуру.','Размен на e4 меняет центр; в варианте Панова изолированная d-пешка даёт активность и требует точности.','Механический Bf5 в неподходящей позиции; лишние ходы пешками до развития; недооценка атаки на слона g6.','Завершите развитие; сравните подрыв c5 с удержанием d5. Не меняйте активную фигуру только ради размена.'),
'queens':("Queen's Gambit",'Ферзевый гамбит','Пешка c4 атакует d5. Развивайте Nc3/Nf3, слонов и короля; после размена в центре определите, нужен ли пешечный нажим или игра по открытой линии.','В отказанном гамбите выбирайте освобождающий c5 или e5 с подготовкой. В принятом — не удерживайте пешку c4 за счёт катастрофического отставания в развитии.','Типовые структуры: карлсбадская, изолированная ферзевая пешка, висячие пешки. План зависит от структуры, а не только от названия дебюта.','Автоматическая атака меньшинства без оценки фигур; удержание лишней пешки; слабое e4 после неподготовленного продвижения.','Сначала классифицируйте пешечный центр, затем выберите открываемую линию и худшую фигуру для улучшения.'),
'slav':('Slav Defense','Славянская защита','Давите на d5 и развивайтесь. После dxc4 часто нужен a4 против b5. Разменная структура симметрична, но планы определяются активностью фигур.','c6 поддерживает d5 и сохраняет выход слона c8. Решайте, когда брать на c4, и проверяйте a4. В полуславянской e6 меняет развитие слона.','Пешечный треугольник c6–d5–e6 устойчив, но слон c8 требует решения. После размена cxd5 структура может стать симметричной.','Удержание c4 без развития; шаблонный Bf5 при тактическом ударе; смешение планов славянской и полуславянской.','Выведите фигуры, оцените подготовку e5/c5 и не допускайте бесполезной пассивности.'),
'kingsindian':("King's Indian Defense",'Староиндийская защита','Белые занимают пространство d4/e4/c4. При закрытии центра d5 часто возможна игра на ферзевом фланге; перед этим проверьте королевскую безопасность и f5 чёрных.','Фианкетто, рокировка и центральный подрыв e5 или c5. Атака на королевском фланге должна соответствовать закрытому центру; при открытом центре приоритет меняется.','Белые имеют больше пространства; слон g7 давит на центр. Закрытый и открытый центр требуют разных темпов и планов.','Ранний f5 без развития; одинаковая атака во всех структурах; потеря диагонали g7–a1 без компенсации.','Определите положение центра. Лишь затем планируйте фланговый пешечный штурм или вскрытие центральных линий.'),
'nimzo':('Nimzo-Indian Defense','Защита Нимцовича','Выбирайте e3, Qc2 или a3 по желаемой структуре. После Bxc3 примите решение о пешках и паре слонов. Не продвигайте e4, не оценив связку коня c3.','Bb4 затрудняет e4. Сравнивайте сохранение слона и Bxc3; своевременные d5 или c5 атакуют центр. Сдвоенные пешки — цель только при возможности на них давить.','Размен на c3 может дать чёрным структурную цель, белым — пару слонов. Центральные поля e4 и d5 определяют взаимодействие фигур.','Размен слона без плана; пассивность против пары слонов; продвижение пешек под связкой без проверки конкретного ответа.','Оцените, кто выигрывает от раскрытия позиции. Выберите подрыв с учётом двух слонов и пешечных слабостей.'),
}

def main():
    data=json.loads((ROOT/'web/curriculum.json').read_text());eco=json.loads((ROOT/'web/eco.json').read_text());summary={}
    for course in data['courses']:
        if course['id'] not in GUIDES:continue
        prefix,title,white,black,structure,mistakes,transition=GUIDES[course['id']]
        candidates=[r for r in eco if r['name'].startswith(prefix)]
        lines=list(course['variations']);seen={r['pgn'] for r in lines}
        for r in sorted(candidates,key=lambda r:(len(r['pgn'].split()),r['name'])):
            if r['pgn'] in seen:continue
            seen.add(r['pgn']);b=chess.Board()
            for san in r['pgn'].split():b.push_san(san)
            lines.append({'id':r['id'],'opening_id':course['id'],'name':r['name'].replace(prefix,title,1),'eco':r['eco'],'pgn':r['pgn'],'source_name':r['name'],'plies':len(r['pgn'].split())})
        guide={'white':white,'black':black,'structure':structure,'mistakes':mistakes,'transition':transition,'phases':[{'name':'Развитие и безопасность','until':10,'task':'Проверьте угрозы, развитие лёгких фигур и возможность рокировки.'},{'name':'Борьба за центр','until':20,'task':'Сравните пешечные подрывы, опорные поля и активность фигур.'},{'name':'Планы миттельшпиля','until':1000,'task':'Определите пешечную структуру и план улучшения худшей фигуры.'}]}
        pack={'variations':lines,'guide':guide,'source':'lichess-org/chess-openings CC0 + original Russian plans','max_plies':max(len(v['pgn'].split()) for v in lines)}
        (ROOT/'web/courses'/(course['id']+'.json')).write_text(json.dumps(pack,ensure_ascii=False,separators=(',',':')))
        course.update(deep=True,chapters=len(lines),max_plies=pack['max_plies']);summary[course['id']]={'chapters':len(lines),'max_plies':pack['max_plies']}
    (ROOT/'web/curriculum.json').write_text(json.dumps(data,ensure_ascii=False,separators=(',',':')))
    print(summary)
if __name__=='__main__':main()
